<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import AppDialog from './AppDialog.vue';
import {ApiError} from '../services/api';
type Link={aditivo:string;base:string|null;justificativa:string;revisao:number};
const props=defineProps<{documents:Array<{numero_registro:string;tipo:string}>;links:Link[];request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>}>();
const emit=defineEmits<{close:[];saved:[message:string]}>();
const amendments=computed(()=>props.documents.filter(item=>/termo aditivo/i.test(item.tipo)&&/conven[çc][ãa]o coletiva/i.test(item.tipo)));
const bases=computed(()=>props.documents.filter(item=>!/aditivo/i.test(item.tipo)&&/conven[çc][ãa]o coletiva/i.test(item.tipo)));
const amendment=ref(''),base=ref(''),reason=ref(''),revision=ref(0),busy=ref(false),error=ref(''),conflict=ref(false),refreshed=ref(false),records=ref<Link[]>(props.links);let alive=true;
const current=computed(()=>records.value.find(item=>item.aditivo===amendment.value));
watch(()=>props.links,value=>{records.value=value;});
watch(amendment,()=>{base.value=current.value?.base??'';revision.value=current.value?.revisao??0;reason.value='';error.value='';conflict.value=false;refreshed.value=false;});
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{const catalog=await props.request<{vinculos:Link[]}>('/api/contexto/interpretacoes');if(!alive)return;records.value=catalog.vinculos;revision.value=current.value?.revisao??0;conflict.value=false;refreshed.value=true;}catch(cause){if(alive)error.value=(cause as Error).message;}finally{if(alive)busy.value=false;}}
async function save(){if(busy.value||conflict.value||!amendment.value||reason.value.trim().length<8)return;busy.value=true;error.value='';try{await props.request('/api/contexto/vinculos','POST',{aditivo:amendment.value,base:base.value||null,justificativa:reason.value.trim(),revisao:revision.value});if(alive)emit('saved',base.value?'Vínculo do aditivo atualizado.':'Aditivo marcado como não vinculado.');}catch(cause){if(alive){error.value=(cause as Error).message;conflict.value=cause instanceof ApiError&&cause.status===409;}}finally{if(alive)busy.value=false;}}
onBeforeUnmount(()=>{alive=false;});
</script>
<template><AppDialog title="Gerenciar vínculos de aditivos" :busy="busy" @close="emit('close')"><p>Confira o aditivo e a CCT antes de registrar a decisão deste escritório. Cada alteração exige uma justificativa.</p><p v-if="!amendments.length" role="status">Ainda não há aditivos de convenção coletiva disponíveis.</p><form v-else class="vue-form" @submit.prevent="save"><label>Aditivo<select v-model="amendment" required :disabled="busy"><option value="">Selecione um aditivo</option><option v-for="item in amendments" :key="item.numero_registro">{{ item.numero_registro }}</option></select></label><template v-if="amendment"><article class="document-related"><small>Decisão registrada</small><span v-if="current" class="status-badge">Revisão {{ current.revisao }}</span><p>{{ current?.base?'Vinculado à CCT '+current.base:current?'Não vinculado':'Ainda não avaliado' }}</p><p v-if="current?.justificativa">{{ current.justificativa }}</p></article><label>CCT de destino<select v-model="base" :disabled="busy"><option value="">Rejeitar ou remover vínculo</option><option v-for="item in bases" :key="item.numero_registro">{{ item.numero_registro }}</option></select></label><label>Justificativa da decisão<textarea v-model="reason" required minlength="8" maxlength="2000" :disabled="busy"></textarea></label><article class="document-related"><small>Decisão a salvar</small><p>{{ amendment }} → {{ base?'Vincular à CCT '+base:current?.base?'Remover vínculo com a CCT':'Rejeitar vínculo com CCT' }}</p></article><p class="decision-note">A alteração exige atualizar a consolidação antes de revisar ou gerar relatórios finais.</p></template><p v-if="error" role="alert">{{ error }}</p><section v-if="conflict" class="document-related"><p>A decisão foi alterada em outra aba. Atualize a decisão registrada e compare com seu rascunho antes de salvar novamente.</p><button class="secondary" type="button" :disabled="busy" @click="refresh">Atualizar decisão registrada</button></section><p v-if="refreshed" role="status">Decisão registrada atualizada. Seu destino e sua justificativa foram preservados; confira as diferenças antes de salvar.</p><footer><button class="secondary" type="button" :disabled="busy" @click="emit('close')">Cancelar</button><button class="primary" type="submit" :disabled="busy||conflict||!amendment||reason.trim().length<8">{{ busy?'Salvando…':'Salvar decisão' }}</button></footer></form></AppDialog></template>

<style scoped>
.document-related .status-badge{margin-left:12px}.document-related p{white-space:pre-wrap;overflow-wrap:anywhere}.decision-note{font-size:13px;color:var(--muted);line-height:1.6}
</style>
